71	    Err = SMDiagnostic(Filename, SourceMgr::DK_Error,
72	                       "Could not open input file: " + EC.message());
73	    return nullptr;
74	  }
75	
76	  return parseAssembly(FileOrErr.get()->getMemBufferRef(), Err, Context, Slots);
77	}
